from solution import choose_num
import math
import pytest
from hypothesis import given
import hypothesis.strategies as st


def ref_int(x, y):
    if x > y:
        return -1
    best = -1
    for n in range(x, y + 1):
        if n % 2 == 0:
            if n > best:
                best = n
    return best


def ref_general(x, y):
    if x > y:
        return -1
    hi = math.floor(y)
    if hi % 2 != 0:
        hi -= 1
    if hi >= x:
        return hi
    return -1


def test_example_12_15():
    assert choose_num(12, 15) == 14


def test_example_13_12():
    assert choose_num(13, 12) == -1


@given(st.integers(min_value=1, max_value=200), st.integers(min_value=1, max_value=200))
def test_int_matches_reference(x, y):
    assert choose_num(x, y) == ref_int(x, y)


@given(st.integers(min_value=1, max_value=200), st.integers(min_value=1, max_value=200))
def test_int_result_in_range_and_even(x, y):
    r = choose_num(x, y)
    if r == -1:
        # no even in range
        assert ref_int(x, y) == -1
    else:
        assert r % 2 == 0
        assert x <= r <= y


@given(st.integers(min_value=1, max_value=200), st.integers(min_value=1, max_value=200))
def test_int_maximality(x, y):
    r = choose_num(x, y)
    if r != -1:
        # no even strictly greater than r within range
        for n in range(r + 1, y + 1):
            assert n % 2 != 0, f"larger even {n} exists in [{x},{y}] but got {r}"


@given(st.integers(min_value=1, max_value=200), st.integers(min_value=1, max_value=200))
def test_int_minus_one_iff_no_even(x, y):
    r = choose_num(x, y)
    has_even = any(n % 2 == 0 for n in range(x, y + 1)) if x <= y else False
    assert (r == -1) == (not has_even)


@given(st.integers(min_value=1, max_value=200), st.integers(min_value=1, max_value=200))
def test_x_greater_than_y_returns_minus_one(x, y):
    # for x > y range is empty
    if x > y:
        assert choose_num(x, y) == -1
    # also swapped order check: larger first arg
    lo = min(x, y)
    hi = max(x, y)
    if lo != hi:
        assert choose_num(hi, lo) == -1


def test_singleton_even():
    assert choose_num(2, 2) == 2
    assert choose_num(4, 4) == 4
    assert choose_num(100, 100) == 100


def test_singleton_odd():
    assert choose_num(1, 1) == -1
    assert choose_num(3, 3) == -1
    assert choose_num(99, 99) == -1


def test_adjacent_pairs():
    # touching intervals of size 2 covering spec boundaries
    assert choose_num(12, 13) == 12
    assert choose_num(13, 14) == 14
    assert choose_num(13, 13) == -1
    assert choose_num(14, 14) == 14
    assert choose_num(13, 15) == 14
    assert choose_num(14, 15) == 14
    assert choose_num(15, 16) == 16
    assert choose_num(15, 15) == -1


def test_no_even_small_ranges():
    assert choose_num(1, 1) == -1
    assert choose_num(3, 5) == 4  # sanity: has even
    # odd singleton then next odd: only one even between tested above
    # two consecutive odds contain exactly one even
    assert choose_num(7, 9) == 8
    assert choose_num(9, 11) == 10


@given(
    st.floats(min_value=1.0, max_value=200.0, allow_nan=False, allow_infinity=False),
    st.floats(min_value=1.0, max_value=200.0, allow_nan=False, allow_infinity=False),
)
def test_float_matches_reference(x, y):
    assert choose_num(x, y) == ref_general(x, y)


@given(
    st.floats(min_value=1.0, max_value=200.0, allow_nan=False, allow_infinity=False),
    st.floats(min_value=1.0, max_value=200.0, allow_nan=False, allow_infinity=False),
)
def test_float_result_is_int_even_in_range(x, y):
    r = choose_num(x, y)
    expected = ref_general(x, y)
    assert r == expected
    if r != -1:
        assert isinstance(r, int)
        assert r % 2 == 0
        assert x <= r <= y


def test_float_examples():
    # biggest even integer in [12.5, 15.5] is 14
    assert choose_num(12.5, 15.5) == 14
    # 14 is below lower bound, 16 above upper bound
    assert choose_num(14.5, 15.5) == -1
    # upper bound itself even integer
    assert choose_num(13.0, 14.0) == 14
    # range containing no even integer
    assert choose_num(13.1, 13.9) == -1
    # float upper bound just below an even
    assert choose_num(12.0, 13.9) == 12


@given(st.integers(min_value=1, max_value=200))
def test_monotone_in_y(x):
    # fixing x, extending y cannot decrease the answer (treating -1 as -1)
    prev = choose_num(x, x)
    for y in range(x + 1, min(x + 20, 201)):
        cur = choose_num(x, y)
        assert cur >= prev, f"non-monotone at x={x}: y-1 gave {prev}, y gave {cur}"
        prev = cur
